// ── PreToolUse deny rules (playbook-canon-parity, unchanged) ──

function patternOf(p             )                                                       {
	return typeof p === "string" ? { pattern: p, caseInsensitive: null } : { pattern: p.pattern, caseInsensitive: p.caseInsensitive };
}

/** The value a rule matches: the first listed field holding a non-empty string (Python `a or b or ""`). */
export function fieldValue(toolInput                         , fields                      )         {
	for (const f of fields) {
		const v = toolInput[f];
		if (typeof v === "string" && v.length > 0) return v;
	}
	return "";
}

function compiled(p             , ruleFlag         )         {
	const { pattern, caseInsensitive } = patternOf(p);
	return new RegExp(pattern, (caseInsensitive ?? ruleFlag) ? "i" : "");
}

/**
 * Applies deny rules in order to one PreToolUse input; the first match wins
 * (deny-guard checks Deny 1, then 2, 3 and 4 and exits on the first). An
 * input that is not an object, or names no tool, is allowed (fail open).
 */
export function evaluateDeny(rules                     , input         )               {
	if (!input || typeof input !== "object") return { exitCode: 0, stderr: "", ruleId: null };
	const hook = input             ;
	const tool = typeof hook.tool_name === "string" ? hook.tool_name : "";
	const toolInput = hook.tool_input && typeof hook.tool_input === "object" ? (hook.tool_input                           ) : {};
	for (const rule of rules) {
		if (!rule.tools.includes(tool            )) continue;
		const value = fieldValue(toolInput, rule.fields);
		if (!rule.allOf.every((p) => compiled(p, rule.caseInsensitive).test(value))) continue;
		return { exitCode: 2, stderr: `DENY (${rule.source}): ${rule.message.split("{value}").join(value)}`, ruleId: rule.id };
	}
	return { exitCode: 0, stderr: "", ruleId: null };
}

/** The path reminders that apply to one PreToolUse Edit/Write/MultiEdit input (REQ-PCP8), in pack order. */
export function matchPaths(paths                     , input         )             {
	if (!input || typeof input !== "object") return [];
	const toolInput = (input             ).tool_input;
	const path = toolInput && typeof toolInput === "object" && typeof (toolInput                           ).file_path === "string" ? ((toolInput                         ).file_path) : "";
	if (!path) return [];
	return paths.filter((p) => new RegExp(p.pattern, p.caseInsensitive ? "i" : "").test(path));
}

// ── the four layers (agent-homes REQ-AGH15, REQ-AGH16) ──

/** REQ-AGH15: the layers, highest first. */
export const RULE_LAYERS                       = ["org", "room", "user", "agent"];

/** Stricter is higher. An unknown effect reads as deny (fail closed). */
export function strictness(effect                     )         {
	return effect === "allow" ? 0 : effect === "ask" ? 1 : 2;
}

/** A layer's rank, 0 highest. An unknown layer ranks as `agent`: it can still only narrow. */
export function layerRank(layer                    )         {
	const i = RULE_LAYERS.indexOf(layer             );
	return i === -1 ? RULE_LAYERS.length - 1 : i;
}

/** An existing pack deny rule as a layer rule (the org pack today; room and user packs once they carry deny rules). */
export function packDenyToLayer(rule          , layer           , roomId                = null)            {
	return { ...rule, layer, roomId, effect: "deny", on: ["tool"] };
}

const WORD_CHAR = /[\p{L}\p{N}_]/u;

function isWordChar(ch                    )          {
	return Boolean(ch) && WORD_CHAR.test(ch          );
}

function phraseForm(s        , caseInsensitive         )         {
	const t = s.normalize("NFKC").replace(/\s+/g, " ");
	return caseInsensitive ? t.toLowerCase() : t;
}

/**
 * REQ-AGH15: does `text` contain `phrase` as words? Literal, never a pattern
 * and never a topic. Spacing runs read as one space, compatible characters
 * alike (NFKC). An edge of the phrase that is a letter, digit or `_` must not
 * touch another one in the text: "PR-" matches "PR-12" and "see PR-12", not
 * "SPR-12"; "deploy" does not match "redeploy".
 */
export function containsPhrase(text        , phrase        , caseInsensitive = true)          {
	const p = phraseForm(phrase, caseInsensitive).trim();
	if (!p) return false;
	const t = phraseForm(text, caseInsensitive);
	const wordStart = isWordChar(p[0]);
	const wordEnd = isWordChar(p[p.length - 1]);
	let i = t.indexOf(p);
	while (i !== -1) {
		const before = i === 0 ? undefined : t[i - 1];
		const after = t[i + p.length];
		if ((!wordStart || !isWordChar(before)) && (!wordEnd || !isWordChar(after))) return true;
		i = t.indexOf(p, i + 1);
	}
	return false;
}

/** Whether the action reaches anyone the rule's `who` names. People not given read as someone else (fail closed). */
function reachesOthers(who                             , act             )          {
	if (!Array.isArray(act.people)) return true;
	const allowed = Array.isArray(act.allowed) ? act.allowed : [];
	return act.people.some((p) => p !== act.ownerId && (who === "not-owner" || !allowed.includes(p)));
}

function toolMatch(rule           , input         )                {
	if (!Array.isArray(rule.tools) || !Array.isArray(rule.fields) || !Array.isArray(rule.allOf) || rule.allOf.length === 0) return null;
	if (!input || typeof input !== "object") return null;
	const hook = input             ;
	const tool = typeof hook.tool_name === "string" ? hook.tool_name : "";
	if (!rule.tools.includes(tool            )) return null;
	const toolInput = hook.tool_input && typeof hook.tool_input === "object" ? (hook.tool_input                           ) : {};
	const value = fieldValue(toolInput, rule.fields);
	return rule.allOf.every((p) => compiled(p, rule.caseInsensitive).test(value)) ? value : null;
}

function textMatch(rule           , text        )          {
	const phrases = Array.isArray(rule.phrases) ? rule.phrases : [];
	const anyOf = Array.isArray(rule.anyOf) ? rule.anyOf : [];
	if (phrases.length === 0 && anyOf.length === 0) return true;
	return phrases.some((p) => containsPhrase(text, p, rule.caseInsensitive)) || anyOf.some((p) => compiled(p, rule.caseInsensitive).test(text));
}

/** Whether one rule applies to one action; the matched tool value (or "") when it does, else null. */
export function ruleApplies(rule           , act             )                {
	if (!rule || !Array.isArray(rule.on) || !rule.on.includes(act.action)) return null;
	// bees-custom-rules REQ-BCR12: a sentence rule is the Bee's own instruction, followed through its prompt; no check reads it.
	if (rule.kind === "sentence") return null;
	// REQ-AGH15: a room pack's rule applies only when acting in that room.
	if (rule.layer === "room" && (!act.roomId || rule.roomId !== act.roomId)) return null;
	if (Array.isArray(rule.rooms) && rule.rooms.length > 0 && !(act.roomId && rule.rooms.includes(act.roomId))) return null;
	if (rule.who && !reachesOthers(rule.who, act)) return null;
	if (act.action === "tool") return toolMatch(rule, act.input);
	return textMatch(rule, typeof act.text === "string" ? act.text : "") ? "" : null;
}

/**
 * REQ-AGH15, REQ-AGH16: the decision for one action over every layer's rules.
 * Rules are taken highest layer first (pack order within a layer); the
 * strictest match decides, and on a tie the highest layer's rule is the one
 * reported. An `allow` decides nothing on its own: with no deny or ask the
 * action is allowed whether or not an allow matched.
 */
export function evaluateLayers(rules                      , act             )                {
	const ordered = rules.map((rule, i) => ({ rule, i })).sort((a, b) => layerRank(a.rule.layer) - layerRank(b.rule.layer) || a.i - b.i);
	const matched           = [];
	let best                                            = null;
	for (const { rule } of ordered) {
		const value = ruleApplies(rule, act);
		if (value === null) continue;
		matched.push(rule.id);
		if (!best || strictness(rule.effect) > strictness(best.rule.effect)) best = { rule, value };
	}
	if (!best || strictness(best.rule.effect) === 0) return { effect: "allow", rule: null, matched };
	const { rule, value } = best;
	return {
		effect: strictness(rule.effect) === 1 ? "ask" : "deny",
		rule: { id: rule.id, layer: rule.layer, roomId: rule.roomId ?? null, message: rule.message.split("{value}").join(value), source: rule.source },
		matched,
	};
}

/** A tool decision in the hook's terms: a deny exits 2 with `DENY (<source>): <message>`; an ask or allow exits 0. */
export function layerHookDecision(rules                      , input         , act                                        = {})                                                      {
	const d = evaluateLayers(rules, { ...act, action: "tool", input });
	if (d.effect !== "deny" || !d.rule) return { exitCode: 0, stderr: "", ruleId: d.rule ? d.rule.id : null, effect: d.effect };
	return { exitCode: 2, stderr: `DENY (${d.rule.source}): ${d.rule.message}`, ruleId: d.rule.id, effect: "deny" };
}
